function check(input, actual, expected) {
  const [operations, args] = input;
  const values = args[0][0];
  if (!Array.isArray(actual) || actual.length !== operations.length || actual[0] !== null) return false;
  const nodes = new Map();
  for (const value of values) nodes.set(value, (nodes.get(value) || 0) + 1);
  const picked = new Map();
  for (let i = 1; i < actual.length; i++) {
    if (!nodes.has(actual[i])) return false;
    picked.set(actual[i], (picked.get(actual[i]) || 0) + 1);
  }
  // A fair pick returns each value about calls * (its nodes / all nodes) times; allow five standard deviations.
  const calls = actual.length - 1;
  for (const [value, count] of nodes) {
    const share = count / values.length;
    const mean = calls * share;
    const deviation = Math.sqrt(calls * share * (1 - share));
    if (Math.abs((picked.get(value) || 0) - mean) > 5 * deviation + 3) return false;
  }
  return true;
}

