function validate([operations, args]) {
  const values = args[0][0];
  if (values.length < 1 || values.length > 10000) return 'The list needs 1 to 10^4 nodes.';
  if (values.some(v => v < -10000 || v > 10000)) return 'Each node value is between -10^4 and 10^4.';
  if (operations.slice(1).some(op => op !== 'getRandom')) return 'After the constructor, only getRandom is called.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls are made to getRandom.';
  return null;
}

