class Solution {
  constructor(head) {
    this.head = head;
  }

  getRandom() {
    let chosen = this.head.val;
    let count = 1;
    let node = this.head.next;
    while (node !== null) {
      count++;
      if (Math.random() < 1 / count) {
        chosen = node.val;
      }
      node = node.next;
    }
    return chosen;
  }
}

