class Solution {
  constructor(head) {
    // Copy the values into an array once, then pick a random index per call.
    this.values = [];
    for (let node = head; node; node = node.next) this.values.push(node.val);
  }
  getRandom() {
    return this.values[Math.floor(Math.random() * this.values.length)];
  }
}

